function traceVisibilityEligibilityResult(
  scene,
  session,
  entity,
  simulationTimeMs,
  eligible,
  reason,
  policyDetails = null,
) {
  if (spatialTrace.isEnabled()) {
    spatialTrace.recordVisibilityEligibility(scene, session, entity, {
      eligible,
      reason,
      simulationTimeMs,
      policyDetails,
    });
  }
  return eligible;
}

