function getActiveSceneMovementInterval(scene) {
  const endSimTimeMs = Math.max(
    0,
    toFiniteNumber(
      scene && scene._activeTickNowMs,
      scene && typeof scene.getCurrentSimTimeMs === "function"
        ? scene.getCurrentSimTimeMs()
        : 0,
    ),
  );
  const deltaSeconds = Math.max(
    0,
    toFiniteNumber(scene && scene._activeTickDeltaSeconds, 0),
  );
  return {
    deltaSeconds,
    endSimTimeMs,
    startSimTimeMs: Math.max(0, endSimTimeMs - (deltaSeconds * 1000)),
  };
}

function prepareActiveNativeSubwarpPlan(scene) {
  if (!scene || !(scene.dynamicEntities instanceof Map)) {
    return null;
  }
  const interval = getActiveSceneMovementInterval(scene);
  const activeTickSequence = toInt(scene._activeTickSequence, 0);
  const previousPlan = scene._activeNativeSubwarpPlan;
  if (
    previousPlan &&
    previousPlan.activeTickSequence === activeTickSequence &&
    previousPlan.startSimTimeMs === interval.startSimTimeMs &&
    previousPlan.targetSimTimeMs === interval.endSimTimeMs &&
    previousPlan.sceneEntitiesOwner === scene.dynamicEntities
  ) {
    return previousPlan;
  }
  const plan = destinyNativeSubwarpController.planSceneInterval(
    scene,
    interval.startSimTimeMs,
    interval.endSimTimeMs,
    {
      activeTickSequence,
      advanceMovement,
      cloneEntity: cloneDynamicEntityForDestinyPresentation,
      previousFrame: scene._nativeSubwarpFrame,
      shouldAdvance: (entity) => (
        !entity.pendingDock &&
        toInt(entity._lastMovementAdvancedTickSequence, 0) !==
          activeTickSequence
      ),
    },
  );
  scene._activeNativeSubwarpPlan = plan;
  return plan;
}

function refreshActiveNativeSubwarpPlan(scene) {
  const plan = prepareActiveNativeSubwarpPlan(scene);
  const activeTickSequence = toInt(scene && scene._activeTickSequence, 0);
  if (
    !plan ||
    plan.complete !== true ||
    destinyNativeSubwarpController.isSceneIntervalPlanCurrent(
      plan,
      scene,
      {
        // A destruction catch-up may already have consumed and removed a ball
        // before the ordinary movement phase. Remaining live balls must still
        // be compared with the detached start scene, while consumed balls are
        // already at their authored endpoint.
        shouldCompare: (entity) => (
          toInt(entity && entity._lastMovementAdvancedTickSequence, 0) !==
            activeTickSequence
        ),
      },
    )
  ) {
    return plan;
  }
  // Do not rebuild membership or the tick-start sweep snapshot here. Scene
  // producers may have spawned, replaced, teleported, or directly displaced
  // balls since the behavior phase. Reproject only the exact sources retained
  // by the original plan through its already-authored Carbon frames.
  return destinyNativeSubwarpController.refreshSceneIntervalProjections(
    plan,
    scene,
    {
      advanceMovement,
      cloneEntity: cloneDynamicEntityForDestinyPresentation,
      shouldAdvance: (entity) => (
        !entity.pendingDock &&
        toInt(entity._lastMovementAdvancedTickSequence, 0) !==
          activeTickSequence
      ),
    },
  );
}

function buildActiveSceneMovementView(scene, plan, sourceEntity = null) {
  if (!plan || plan.complete !== true) {
    return scene;
  }
  const sourceEntityKey = getEntityMapKey(sourceEntity && sourceEntity.itemID);
  const authoredTargetSnapshotsByID =
    sourceEntityKey !== null &&
    plan.sourceEntitiesByID instanceof Map &&
    plan.sourceEntitiesByID.get(sourceEntityKey) === sourceEntity &&
    plan.rawMovementTargetSnapshotsBySourceID instanceof Map
      ? plan.rawMovementTargetSnapshotsBySourceID.get(sourceEntityKey)
      : null;
  return {
    getEntityByID(entityID) {
      const entityKey = getEntityMapKey(entityID);
      if (
        authoredTargetSnapshotsByID instanceof Map &&
        entityKey !== null &&
        authoredTargetSnapshotsByID.has(entityKey)
      ) {
        const authoredTarget = authoredTargetSnapshotsByID.get(entityKey);
        return authoredTarget
          ? cloneDynamicEntityForDestinyPresentation(authoredTarget)
          : null;
      }
      const liveEntity = typeof scene.getEntityByID === "function"
        ? scene.getEntityByID(entityID)
        : null;
      if (
        !liveEntity ||
        entityKey === null ||
        !(plan.sourceEntitiesByID instanceof Map) ||
        plan.sourceEntitiesByID.get(entityKey) !== liveEntity ||
        !(plan.projectedEntitiesByID instanceof Map) ||
        !(plan.startSnapshotsByID instanceof Map)
      ) {
        return liveEntity;
      }
      const projectedEntity = plan.projectedEntitiesByID.get(entityKey);
      const startSnapshot = plan.startSnapshotsByID.get(entityKey);
      if (!projectedEntity || !startSnapshot) {
        return liveEntity;
      }
      const movementView = cloneDynamicEntityForDestinyPresentation(
        projectedEntity,
      );
      movementView.lastMotionDebug = {
        ...(movementView.lastMotionDebug || {}),
        previousPosition: cloneVector(startSnapshot.position),
        previousVelocity: cloneVector(startSnapshot.velocity),
      };
      return movementView;
    },
  };
}

function forgetEntityFromNativeSubwarpPlans(scene, entityOrID) {
  if (!scene) {
    return false;
  }
  const removedFrame = destinyNativeSubwarpController.forgetEntity(
    scene._nativeSubwarpFrame,
    entityOrID,
  );
  const removedPlan = destinyNativeSubwarpController.forgetSceneIntervalEntity(
    scene._activeNativeSubwarpPlan,
    entityOrID,
  );
  return removedFrame || removedPlan;
}

function advanceEntityForActiveSceneTick(scene, entity) {
  const activeTickSequence = toInt(scene && scene._activeTickSequence, 0);
  const interval = getActiveSceneMovementInterval(scene);
  if (
    !scene ||
    !entity ||
    activeTickSequence <= 0 ||
    toInt(entity._lastMovementAdvancedTickSequence, 0) === activeTickSequence
  ) {
    return {
      advanced: false,
      result: {
        changed: false,
        movementAlreadyAdvanced: true,
      },
    };
  }
  // Entity-loop module and assistance work can change movement attributes
  // after the shared post-subsystem barrier. Reproject remaining exact sources
  // immediately before consumption while retaining the tick's authored
  // behavior frames and start snapshots.
  const plan = refreshActiveNativeSubwarpPlan(scene);
  const nativeResult = destinyNativeSubwarpController.consumeSceneIntervalEntity(
    plan,
    entity,
  );
  const rawDeltaSeconds =
    plan &&
    plan.complete === true &&
    plan.resynchronized === true &&
    Number.isFinite(Number(plan.effectiveStartSimTimeMs)) &&
    Number.isFinite(Number(plan.targetSimTimeMs))
      ? Math.max(
          0,
          (Number(plan.targetSimTimeMs) -
            Number(plan.effectiveStartSimTimeMs)) / 1000,
        )
      : interval.deltaSeconds;
  const result = nativeResult === null
    ? advanceMovement(
        entity,
        buildActiveSceneMovementView(scene, plan, entity),
        rawDeltaSeconds,
        interval.endSimTimeMs,
      )
    : nativeResult;
  entity._lastMovementAdvancedTickSequence = activeTickSequence;
  entity._lastMovementAdvancedAtMs = interval.endSimTimeMs;
  return {
    advanced: true,
    result,
  };
}

function finalizeActiveNativeSubwarpPlan(scene) {
  if (!scene) {
    return null;
  }
  const plan = scene._activeNativeSubwarpPlan;
  const activeTickSequence = toInt(scene._activeTickSequence, 0);
  const planCanAuthorEndpoint = Boolean(
    plan &&
    plan.complete === true &&
    plan.activeTickSequence === activeTickSequence &&
    plan.sceneEntitiesOwner === scene.dynamicEntities &&
    plan.failureReason !== "identity-conflict",
  );
  if (planCanAuthorEndpoint) {
    const lastSegmentFrame =
      Array.isArray(plan.segments) && plan.segments.length > 0
        ? plan.segments[plan.segments.length - 1].frame
        : null;
    const endpointStartsAtTarget = Boolean(
      plan.endpointFrame &&
      Math.abs(
        Number(plan.endpointFrame.frameStartMs) -
          Number(plan.targetSimTimeMs),
      ) <= 0.000001,
    );
    const finalSegmentEndsAtTarget = Boolean(
      lastSegmentFrame &&
      Math.abs(
        Number(lastSegmentFrame.frameEndMs) -
          Number(plan.targetSimTimeMs),
      ) <= 0.000001,
    );
    if (endpointStartsAtTarget || finalSegmentEndsAtTarget) {
      // The endpoint is future behavior, not part of the completed movement
      // sweep. Re-author it from final live state without replaying movement so
      // post-consume module changes, relocations, and late inserts enter on the
      // immediately following native tick.
      destinyNativeSubwarpController.refreshSceneIntervalProjections(
        plan,
        scene,
        {
          advanceMovement,
          cloneEntity: cloneDynamicEntityForDestinyPresentation,
          shouldAdvance: () => false,
          shouldCarryEndpoint: (entity) => !entity.pendingDock,
        },
      );
    }
  }
  if (
    plan &&
    plan.complete === true &&
    plan.activeTickSequence === activeTickSequence &&
    plan.sceneEntitiesOwner === scene.dynamicEntities &&
    plan.endpointFrame
  ) {
    scene._nativeSubwarpFrame = plan.endpointFrame;
  } else if (plan && plan.failureReason === "identity-conflict") {
    // An ambiguous canonical identity cannot author a safe carried frame.
    // Keep projections/range fail-closed until lifecycle reconciliation
    // restores one exact source per ID.
    scene._nativeSubwarpFrame = null;
  } else {
    const interval = getActiveSceneMovementInterval(scene);
    scene._nativeSubwarpFrame = destinyNativeSubwarpController.prepareFrame(
      scene,
      interval.endSimTimeMs,
      {
        behaviorAtMs: interval.endSimTimeMs,
        previousFrame: null,
      },
    );
    for (const entity of scene.dynamicEntities.values()) {
      if (entity && entity.pendingDock) {
        destinyNativeSubwarpController.forgetEntity(
          scene._nativeSubwarpFrame,
          entity,
        );
      }
    }
  }
  scene._activeNativeSubwarpPlan = null;
  return scene._nativeSubwarpFrame;
}

function abortActiveNativeSubwarpPlan(scene) {
  if (!scene) {
    return false;
  }
  const plan = scene._activeNativeSubwarpPlan;
  if (plan) {
    const frames = new Set([
      ...(Array.isArray(plan.segments)
        ? plan.segments.map((segment) => segment && segment.frame)
        : []),
      plan.endpointFrame,
    ]);
    for (const frame of frames) {
      destinyNativeSubwarpController.clearFrame(frame);
    }
  }
  scene._activeNativeSubwarpPlan = null;
  scene._nativeSubwarpFrame = null;
  return Boolean(plan);
}

